<script setup lang="ts">
import {computed,ref,onBeforeUnmount,onMounted} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import type {ExportJob} from '../../../../shared/contracts';
import {ApiError} from '../../../lib/request';
import {adminApi,errorMessage,timeLabel} from '../api';
import AdminNav from '../components/AdminNav.vue';
const route=useRoute(),router=useRouter();const job=ref<ExportJob|null>(null),jobId=ref(typeof route.query.job==='string'?route.query.job:''),busy=ref(false),error=ref(''),downloadAcknowledged=ref(false),createKey=ref<string|null>(null);
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false;
const labels={pending:'等待导出',running:'正在生成完整包',ready:'导出包已就绪',failed:'导出失败',expired:'导出包已过期'};
const downloadUrl=computed(()=>job.value?.state==='ready'&&job.value.downloadUrl===`/api/v1/admin/exports/${job.value.id}/file`?job.value.downloadUrl:undefined);
function stop(){if(timer)clearTimeout(timer);timer=undefined;}
async function refresh(){stop();if(!jobId.value||busy.value)return;if(!/^[a-f0-9-]{36}$/i.test(jobId.value)){error.value='请输入有效导出编号';return;}busy.value=true;error.value='';downloadAcknowledged.value=false;try{job.value=await adminApi.exportGet(jobId.value);if(!disposed&&['pending','running'].includes(job.value.state))timer=setTimeout(refresh,2000);}catch(e){job.value=null;error.value=errorMessage(e);}finally{busy.value=false;}}
async function create(){if(busy.value)return;stop();busy.value=true;error.value='';job.value=null;downloadAcknowledged.value=false;createKey.value??=crypto.randomUUID();try{const result=await adminApi.exportCreate(createKey.value);jobId.value=result.id;createKey.value=null;await router.replace({path:'/admin/exports',query:{job:result.id}});}catch(e){error.value=errorMessage(e);if(e instanceof ApiError&&e.status<500&&e.code!=='REQUEST_IN_PROGRESS')createKey.value=null;return;}finally{busy.value=false;}await refresh();}
onMounted(()=>{if(jobId.value)void refresh();});onBeforeUnmount(()=>{disposed=true;stop();});
</script>
<template><AdminNav/><span class="eyebrow">完整归档</span><h1>把记录留在自己手里</h1><p class="notice">包含全部私密内容，请保存到受控位置。完整包包含草稿、撤回、软删除记录及未关联原件，不会自动传到外部服务。</p><section class="card"><h2>生成完整导出</h2><p>按服务端快照生成，之后新增或修改的内容不在本包中。就绪后可下载 24 小时；导出过期不会删除源文件。</p><button :disabled="busy||!!job&&['pending','running'].includes(job.state)" @click="create">{{busy?'处理中…':createKey?'重试原导出请求':'生成完整导出'}}</button><p v-if="createKey" class="muted">上次创建结果未核实，请保留本页并用原请求重试。</p><p v-if="error" role="alert" class="error">{{error}}</p><form @submit.prevent="refresh"><label>查找已有导出编号<input v-model="jobId" :disabled="busy||!!createKey" placeholder="可保存带编号的本页地址，稍后回来查看"></label><button :disabled="busy||!jobId||!!createKey">查询 / 刷新状态</button></form><div v-if="job" aria-live="polite"><h2>{{labels[job.state]}}</h2><p>创建于 {{timeLabel(job.createdAt)}}</p><p v-if="job.finishedAt">完成于 {{timeLabel(job.finishedAt)}}</p><p v-if="job.expiresAt">到期 {{timeLabel(job.expiresAt)}}</p><p v-if="job.byteSize!==null">包大小 {{job.byteSize.toLocaleString()}} 字节</p><p v-if="job.error" role="alert" class="error">{{job.error.message}}（{{job.error.code}}）</p><template v-if="downloadUrl"><label class="check"><input v-model="downloadAcknowledged" type="checkbox">我会将包含私密内容的导出包保存到受控位置</label><a v-if="downloadAcknowledged" :href="downloadUrl" download>下载完整 ZIP 包</a><p class="muted">点击后由浏览器下载；请检查实际下载结果。此页面不会把点击记为下载成功。</p><details><summary>文件校验值</summary><p class="hash">{{job.sha256}}</p></details></template></div><p class="muted">恢复由维护工具在空隔离目录执行；这里不提供在线覆盖恢复。</p></section></template>
<style scoped>form{border-top:1px solid var(--line);margin-top:24px;padding-top:20px}label{display:grid;gap:8px;margin:16px 0}.check{display:flex;align-items:start}.check input{margin-top:8px}a{display:inline-block;background:var(--accent);color:white;padding:10px 20px;border-radius:8px}.hash{font-size:12px;overflow-wrap:anywhere}</style>
